#include "stdafx.h"#include "HcdDataCopy.h"bool HcdDataCopy( void *pDestData, eHcdVType destType, void *pSourceData, eHcdVType sourceType ){  switch( sourceType )  {  case ehtDisable:    return false;  case ehtAnalog32:    switch( destType )    {    case ehtAnalog32:      *(tAnalog32*)pDestData = *(tAnalog32*)pSourceData;      break;    case ehtBool:    case ehtEnum:      *(tEnum*)pDestData = *(tAnalog32*)pSourceData;      break;    case ehtDigital32:      *(tDigital32*)pDestData = *(tAnalog32*)pSourceData;      break;    default:      ASSD(0);      return false;    }    break;  case ehtDigital32:    switch( destType )    {    case ehtAnalog32:      *(tAnalog32*)pDestData = *(tDigital32*)pSourceData;      break;    case ehtDigital32:      *(tDigital32*)pDestData = *(tDigital32*)pSourceData;      break;    case ehtBool:    case ehtEnum:      *(tEnum*)pDestData = *(tDigital32*)pSourceData;      break;    default:      ASSD(0);      return false;    }    break;  case ehtBool:  case ehtEnum:    switch( destType )    {    case ehtAnalog32:      *(tAnalog32*)pDestData = *(tEnum*)pSourceData;      break;    case ehtDigital32:     *(tDigital32*)pDestData = *(tEnum*)pSourceData;      break;    case ehtBool:    case ehtEnum:     *(tEnum*)pDestData = *(tEnum*)pSourceData;      break;    default:      ASSD(0);      return false;    }    break;  default:    ASSD(0);    return false;  }  return true;}